// B1 #269: salida de error de las escrituras a Odoo. Ninguna falla queda muda:
// responde success:false con el motivo, en vez de que la ejecución truene sin Respond.
const e = $input.first().json || {};
const err = e.error;
const msg = String((err && typeof err === 'object' ? (err.message || err.description) : err) || e.message || 'sin detalle');
const sinRespuesta = /ECONNRESET|ETIMEDOUT|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|socket hang up|timeout|timed out|429|502|503|504/i.test(msg);
let p = {};
try { p = $('Code - Validar').first().json || {}; } catch (x) { p = {}; }
return [{ json: {
  success: false,
  codigo: sinRespuesta ? 'ODOO_NO_RESPONDE' : 'ODOO_RECHAZO',
  mensaje: sinRespuesta
    ? 'Odoo no respondió. El cambio NO se guardó; vuelve a intentar.'
    : 'Odoo rechazó el cambio y NO se guardó: ' + msg.slice(0, 300),
  attendance_id: p.attendance_id || null
} }];

