// B1 #269: la respuesta refleja el resultado REAL del UPDATE (antes era success:true fijo).
const p = $('Code - Validar').item.json;
const nodo = p.es_bolsa ? 'Odoo - UPDATE Bolsa' : 'Odoo - UPDATE Proyecto';
let upd = [];
try { upd = $(nodo).all().map(i => i.json); } catch (e) { upd = []; }
const escrito = upd.some(u => u && u.id && u.error === undefined);
if (!escrito) {
  return [{ json: { success: false, codigo: 'ODOO_SIN_CONFIRMAR', attendance_id: p.attendance_id,
    mensaje: 'Odoo no confirmó la escritura. El cambio NO se guardó; vuelve a intentar.' } }];
}
return [{ json: {
  success: true,
  attendance_id: p.attendance_id,
  action: p.action,
  manager_approval: true,
  cuenta_id: p.es_bolsa ? p.cuenta_id : null,
  so_id: p.es_bolsa ? null : p.so_id,
  tipo_correccion: p.tipo_correccion,
  mensaje: (p.es_bolsa ? ('Bolsa asignada: ' + p.target_nombre) : ('Proyecto asignado: ' + p.target_nombre)) + ' y horas confirmadas'
} }];
